// spec: specs/pwa-install-prompt.md (1.4) · кейс: .qa/tests/pwa-install-prompt/PWA-04.md
// seed: tests/seed.user.spec.ts (user, сессия ../auth/user.json) · проект iphone (WebKit, iPhone 13 Mini 375) · прод, только просмотр.
// Комментарий программиста #631293: окно открывается вручную из אזור אישי («הוספה למסך הבית»), снуз не учитывается.
// Закрытие «אולי מאוחר יותר» пишет b4s_install_prompt_dismissed_at в localStorage окна теста — storageState НЕ сохраняется,
// файл сессии не меняется. «הוספה עכשיו» не нажимается.
import { test, expect } from '@playwright/test';
import { prepareReadOnly, installDialog, laterButton, LOAD } from './pwa.helpers';

test.use({ storageState: '../auth/user.json' });

test('Вошедший: «הוספה למסך הבית» в אזור אישי открывает окно «אל תחמיצו אף הזדמנות», окно закрывается #631293 #81a046 @iphone @prod-safe', async ({ page, context }) => {
  await prepareReadOnly(context, true);
  await page.addLocatorHandler(page.getByRole('button', { name: 'חיוניים בלבד' }), (b) => b.click());
  await page.goto('/mybusinesses');
  await expect(page, 'сессия user жива (нет перехода на вход)').not.toHaveURL(/\/auth/);

  const item = page.getByText('הוספה למסך הבית', { exact: true }).filter({ visible: true }).first();
  await expect(item, 'пункт «הוספה למסך הבית» в אזור אישי').toBeVisible(LOAD);
  await expect(installDialog(page), 'до нажатия окна нет').toBeHidden();

  await item.scrollIntoViewIfNeeded();
  await item.click();
  await expect(installDialog(page), 'окно установки открыто из пункта меню').toBeVisible(LOAD);
  await expect(page.getByRole('button', { name: 'הוספה עכשיו' }), 'кнопка «הוספה עכשיו»').toBeVisible();

  await laterButton(page).click();
  await expect(installDialog(page), 'окно закрыто').toBeHidden();
});
